    return sum([b]*a)
for a in range(0, 13):
    for b in range(0, 13):
        assert times(a, b) == a*b and (a + 1)*b == a*b + b and a*(b + 1) == a*b + a
        assert a*b == b*a and a*1 == 1*a == a and a*0 == 0*a == 0
        # empty arrays: a rows of b counted by rows and by columns
        assert sum([b]*a) == sum([a]*b) == len([(r, c) for r in range(a) for c in range(b)])
